import {categoryPlan} from '../core/finance-categories.js?v=20261111-v15a';
import {configSection,STAGES,today} from '../core/business.js?v=20261111-v15a';
export function install(ctx){
 const areas=[['company','Empresa e documentos','settings_company'],['budget','Orçamentos','settings_quotes'],['production','Produção e etapas','settings_production'],['finance','Financeiro e extratos','settings_finance'],['reports','Relatórios e PDF','settings_reports'],['appearance','Aparência e menu','settings_appearance']];
 const titles={home:'Visão geral',workflow:'Quadro de pedidos',quotes:'Orçamentos',finance:'Financeiro',bank:'Extratos e conciliação',reports:'Relatórios',clients:'Clientes',products:'Produtos',suppliers:'Fornecedores',assets:'Patrimônio',settings:'Configurações',users:'Usuários',help:'Central de ajuda',usage:'Uso e armazenamento'};
 let section='company';
 const check=(label,name,value)=>`<label class="check-row"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`;
 const text=(label,name,value,attrs='')=>`<label class="field">${label}<textarea name="${name}" ${attrs}>${ctx.esc(value||'')}</textarea></label>`;
 const lines=(label,name,value)=>text(label+' · um por linha',name,(value||[]).join('\n'),'maxlength="10000"');
 const select=(label,name,value,options)=>`<label class="field">${label}<select name="${name}">${options.map(([k,t])=>`<option value="${k}" ${String(value)===k?'selected':''}>${t}</option>`).join('')}</select></label>`;
 function settingsPage(){const available=areas.filter(a=>ctx.can(a[2]));if(!available.some(a=>a[0]===section))section=available[0]?.[0];if(!section)return;const s=ctx.settings,c=configSection(s,section),area=areas.find(a=>a[0]===section),editable=ctx.can(area[2],'edit');
  let body='';
  if(section==='company')body=`${ctx.field('Nome da empresa','company','text',s.company||'Avelon Têxtil','required maxlength="200"')}${ctx.field('Contatos, CNPJ e endereço para documentos','contact','text',s.contact||'','maxlength="1000"')}${ctx.field('Cidade / UF da assinatura','city','text',s.city||'','maxlength="120"')}${ctx.field('Nome de quem assina','signature_name','text',s.signature_name||'','maxlength="200"')}<label class="field">Logo · PNG / JPG até 350 KB<input name="logo_file" type="file" accept="image/png,image/jpeg"></label><label class="field">Assinatura · PNG / JPG até 350 KB<input name="signature_file" type="file" accept="image/png,image/jpeg"></label>${check('Inverter as cores da assinatura para imprimir em fundo branco','signature_invert',s.signature_invert)}${check('Remover a assinatura salva','remove_signature',false)}<p class="note span2">A assinatura é armazenada nas configurações privadas da empresa. Os documentos preservam os dados vigentes na emissão.</p>`;
  if(section==='budget')body=`${select('Cálculo padrão','method',s.method||'markup',[['markup','Acréscimo sobre custo'],['margin','Margem sobre venda']])}${ctx.field('Percentual padrão (%)','percentage','number',s.percentage??30,'required min="0" max="9999" step="0.01"')}${ctx.field('Entrada padrão (%)','deposit_percentage','number',c.deposit_percentage,'required min="0" max="100" step="0.01"')}${ctx.field('Validade (dias)','validity_days','number',c.validity_days,'required min="1" max="365"')}${ctx.field('Prazo estimado de produção (dias úteis após aprovações)','production_days','number',c.production_days,'required min="1" max="365"')}${ctx.field('Formas de pagamento no documento','payment_methods','text',c.payment_methods,'maxlength="500"')}${text('Condições adicionais','conditions',s.conditions,'maxlength="10000"')}${text('Orientações importantes no orçamento','important_notes',c.important_notes,'maxlength="20000"')}${check('Exibir orientações no PDF','show_notes',c.show_notes)}${check('Exibir assinatura no PDF','show_signature',c.show_signature)}${check('Exibir identificação da empresa','show_company',c.show_company)}<div class="span2"><h3>Recibos de adiantamento</h3></div>${ctx.field('Título do recibo','receipt_title','text',c.receipt_title,'required maxlength="120"')}${check('Abrir recibo e entrada ao iniciar a produção','receipt_auto_on_production',c.receipt_auto_on_production)}${text('Mensagem padrão ao cliente no recibo','receipt_message',c.receipt_message,'maxlength="5000"')}${check('Exibir logo no recibo','receipt_show_logo',c.receipt_show_logo)}${check('Exibir assinatura no recibo','receipt_show_signature',c.receipt_show_signature)}<div class="span2"><h3>Pedido pronto · mensagem ao cliente</h3></div>${check('Abrir mensagem ao mover para Pedido pronto','ready_message_auto',c.ready_message_auto)}${text('Mensagem de pedido pronto','ready_message',c.ready_message,'maxlength="5000"')}<p class="note span2">Campos disponíveis: {cliente}, {pedido}, {empresa}, {saldo} e {entrada_percentual}. A mensagem pode ser ajustada antes de copiar.</p><div class="span2"><h3>Recibo final de quitação</h3></div><p class="note span2">Ao finalizar um pedido, o recibo final é emitido automaticamente após a quitação integral registrada no Financeiro. O acesso deve permitir consultar e emitir recibos.</p>${ctx.field('Título do recibo final','final_receipt_title','text',c.final_receipt_title,'required maxlength="120"')}${text('Mensagem de conclusão ao cliente','final_receipt_message',c.final_receipt_message,'maxlength="5000"')}<p class="note span2">As alterações serão usadas nas novas propostas. Orçamentos já emitidos mantêm as informações salvas.</p>`;
  if(section==='production')body=`<div class="span2"><h3>Regras para movimentar pedidos</h3>${check('Exigir a entrada acordada antes de iniciar a produção','require_deposit',c.require_deposit)}${check('Exigir aprovação da arte antes de iniciar a produção','require_art',c.require_art)}${check('Exigir quitação integral para finalizar','require_balance',c.require_balance)}<p class="note">Mover um cartão não registra pagamento. As baixas são feitas no financeiro ou pela conciliação.</p></div>${lines('Técnicas de personalização','techniques',c.techniques)}<div class="span2"><h3>Etapas do quadro</h3><p class="muted">Personalize os nomes, cores e a ordem. Marque Produção nas etapas adicionais que devem exigir entrada e aprovação da arte. As etapas de produção padrão seguem essas regras.</p><div id="stage-editor">${c.stages.map(stageRow).join('')}</div><button type="button" class="secondary" id="add-stage">Adicionar etapa</button></div>`;
  if(section==='finance')body=`${lines('Categorias financeiras · adicione ou altere os nomes','categories',c.categories)}<details class="span2"><summary>Ver plano de categorias numerado</summary>${categoryPlan(c.categories).filter(g=>g.leaves.length).map(g=>`<section><h3>${ctx.esc(g.group)}</h3><strong>${ctx.esc(g.section)}</strong><ul>${g.leaves.map(c=>`<li>${c.code} · ${ctx.esc(c.name)}</li>`).join('')}</ul></section>`).join('')}</details>${lines('Formas de pagamento','payment_methods',c.payment_methods)}${lines('Sócios / responsáveis','partners',c.partners)}${ctx.field('Tolerância de datas para sugestões de conciliação (dias)','reconcile_days','number',c.reconcile_days,'required min="0" max="30"')}${ctx.field('Vida útil padrão de bens (meses)','default_life_months','number',c.default_life_months,'required min="1" max="1200"')}<div class="span2"><h3>Modelo padrão do extrato CSV</h3><p class="muted">Informe a posição das colunas começando em 1. A importação sempre terá uma prévia antes de gravar.</p></div>${select('Separador','csv_separator',c.csv_separator==='\t'?'tab':c.csv_separator,[[';','Ponto e vírgula (;)'],[',','Vírgula (,)'],['tab','Tabulação']])}${check('A primeira linha contém os títulos das colunas','csv_header',c.csv_header)}${ctx.field('Coluna da data','csv_date','number',c.csv_date+1,'required min="1" max="100"')}${ctx.field('Coluna da descrição','csv_description','number',c.csv_description+1,'required min="1" max="100"')}${ctx.field('Coluna do valor com sinal','csv_amount','number',c.csv_amount+1,'required min="1" max="100"')}${ctx.field('Coluna do identificador bancário (0 = ausente)','csv_id','number',c.csv_id+1,'required min="0" max="100"')}<p class="note span2">Entradas positivas, saídas negativas. O identificador do banco ajuda a evitar importações repetidas.</p>`;
  if(section==='reports')body=`${select('Regime padrão','basis',c.basis,[['cash','Caixa · pagamentos realizados'],['accrual','Competência · títulos registrados']])}${check('Exibir logo nos relatórios','show_logo',c.show_logo)}${check('Exibir assinatura nos relatórios','show_signature',c.show_signature)}${check('Considerar depreciação gerencial nos relatórios de patrimônio','include_depreciation',c.include_depreciation)}${text('Rodapé dos relatórios','footer',c.footer,'maxlength="2000"')}<p class="note span2">O relatório gerencial depende dos lançamentos registrados. A escolha do regime não altera pagamentos ou saldos bancários.</p>`;
  if(section==='appearance')body=`${ctx.field('Cor de destaque','accent','color',s.accent||'#ddab63')}${select('Espaçamento das telas','density',c.density,[['comfortable','Confortável'],['compact','Compacto']])}<div class="span2"><h3>Ordem do menu</h3><div id="menu-editor">${[...new Set([...c.menu,...Object.keys(titles)])].filter(k=>titles[k]).map(k=>`<div class="order-row" data-key="${k}"><strong>${titles[k]}</strong><button type="button" class="secondary small" data-up aria-label="Mover ${titles[k]} para cima">↑</button><button type="button" class="secondary small" data-down aria-label="Mover ${titles[k]} para baixo">↓</button></div>`).join('')}</div><p class="muted">Cada usuário verá somente as áreas permitidas para seu acesso.</p></div>`;
  ctx.shell(`${ctx.head('Configurações','Ajuste as regras da empresa e os padrões de cada funcionalidade.')}<div class="tabs">${available.map(a=>`<button data-section="${a[0]}" class="${section===a[0]?'active':''}">${a[1]}</button>`).join('')}</div><section class="panel"><div class="panelhead"><h2>${area[1]}</h2><span class="badge">${editable?'Edição habilitada':'Somente leitura'}</span></div><form id="configuration-form"><fieldset class="panelbody grid2" ${editable?'':'disabled'}>${body}</fieldset><p class="error" id="configuration-error" role="alert"></p>${editable?'<div class="form-actions"><button class="primary" type="submit">Salvar configurações desta área</button></div>':''}</form></section>${section==='finance'?`<section class="panel"><div class="panelhead"><h2>Contas bancárias e caixa</h2>${editable?'<button class="secondary" id="add-account">Adicionar conta</button>':''}</div><div class="table-wrap"><table><thead><tr><th>Conta</th><th>Saldo inicial</th><th>Data inicial</th><th>Situação</th><th></th></tr></thead><tbody>${(ctx.business?.accounts||[]).map(a=>`<tr><td>${ctx.esc(a.name)}</td><td>${ctx.money(a.opening_balance)}</td><td>${ctx.date(a.opening_date)}</td><td>${a.active?'Ativa':'Inativa'}</td><td>${editable?`<button class="secondary small" data-account="${a.id}">Configurar</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`:''}`);
  document.querySelectorAll('[data-section]').forEach(el=>el.onclick=()=>{section=el.dataset.section;settingsPage()});bindOrder();ctx.$('#add-stage')?.addEventListener('click',()=>{const key='step_'+crypto.randomUUID().replaceAll('-','').slice(0,10);ctx.$('#stage-editor').insertAdjacentHTML('beforeend',stageRow({key,label:'Nova etapa',color:'#64748b',enabled:true,requires_production:true}));bindOrder()});ctx.$('#add-account')?.addEventListener('click',()=>accountDialog());document.querySelectorAll('[data-account]').forEach(el=>el.onclick=()=>accountDialog(ctx.business.accounts.find(a=>a.id===el.dataset.account)));
  ctx.$('#configuration-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const f=e.target,fd=new FormData(f),obj=Object.fromEntries(fd),patch={};const list=k=>String(obj[k]||'').split('\n').map(x=>x.trim()).filter(Boolean);const num=k=>Number(obj[k]);const yes=k=>fd.has(k);
   if(section==='company'){for(const k of ['company','contact','city','signature_name'])patch[k]=obj[k];patch.signature_invert=yes('signature_invert');for(const k of ['logo','signature']){const file=fd.get(k+'_file');if(file?.size){if(file.size>350000||!['image/png','image/jpeg'].includes(file.type))throw Error('Use uma imagem PNG ou JPG de até 350 KB.');patch[k]=await fileData(file)}}if(yes('remove_signature'))patch.signature='';}
   if(section==='budget'){if(obj.method==='margin'&&num('percentage')>=100)throw Error('A margem deve ser menor que 100%.');Object.assign(patch,{method:obj.method,percentage:num('percentage'),conditions:obj.conditions,valid_days:num('validity_days'),budget:{...c,deposit_percentage:num('deposit_percentage'),validity_days:num('validity_days'),production_days:num('production_days'),payment_methods:obj.payment_methods,important_notes:obj.important_notes,show_notes:yes('show_notes'),show_signature:yes('show_signature'),show_company:yes('show_company'),receipt_auto_on_completion:true,ready_message_auto:yes('ready_message_auto'),ready_message:obj.ready_message,final_receipt_title:obj.final_receipt_title,final_receipt_message:obj.final_receipt_message,receipt_title:obj.receipt_title,receipt_auto_on_production:yes('receipt_auto_on_production'),receipt_message:obj.receipt_message,receipt_show_logo:yes('receipt_show_logo'),receipt_show_signature:yes('receipt_show_signature')}});}
   if(section==='production'){const stages=[...f.querySelectorAll('[data-stage]')].map(row=>({key:row.dataset.stage,label:row.querySelector('[data-label]').value.trim(),color:row.querySelector('[data-color]').value,enabled:row.querySelector('[data-enabled]').checked,requires_production:row.querySelector('[data-production]').checked}));if(stages.some(x=>!x.label))throw Error('Informe o nome de todas as etapas.');patch.production={...c,stages,techniques:list('techniques'),require_deposit:yes('require_deposit'),require_art:yes('require_art'),require_balance:yes('require_balance')};}
   if(section==='finance')patch.finance={...c,categories:list('categories'),payment_methods:list('payment_methods'),partners:list('partners'),reconcile_days:num('reconcile_days'),default_life_months:num('default_life_months'),csv_separator:obj.csv_separator==='tab'?'\t':obj.csv_separator,csv_date:num('csv_date')-1,csv_description:num('csv_description')-1,csv_amount:num('csv_amount')-1,csv_id:num('csv_id')-1,csv_header:yes('csv_header')};
   if(section==='reports')patch.reports={...c,basis:obj.basis,show_logo:yes('show_logo'),show_signature:yes('show_signature'),include_depreciation:yes('include_depreciation'),footer:obj.footer};
   if(section==='appearance'){patch.accent=obj.accent;patch.appearance={...c,density:obj.density,menu:[...f.querySelectorAll('[data-key]')].map(el=>el.dataset.key)};}
   await ctx.rpc('save_settings',{p_data:patch});await ctx.load();settingsPage();ctx.toast('Configurações salvas para a empresa.');
  }catch(err){ctx.$('#configuration-error').textContent=err.message;button.disabled=false}};
 }
 function stageRow(s){return `<div class="order-row" data-stage="${ctx.esc(s.key)}"><label class="field">Nome<input data-label value="${ctx.esc(s.label)}" maxlength="60" required></label><label class="field">Cor<input type="color" data-color value="${ctx.esc(s.color)}"></label><label class="check-row"><input type="checkbox" data-enabled ${s.enabled?'checked':''} ${['draft','completed'].includes(s.key)?'disabled':''}>Ativa</label><label class="check-row"><input type="checkbox" data-production ${['production','cutting','personalization','sewing','ready'].includes(s.key)?'disabled':''} ${s.requires_production??['production','cutting','personalization','sewing','ready'].includes(s.key)?'checked':''}>Produção</label><button type="button" class="secondary small" data-up aria-label="Mover etapa para cima">↑</button><button type="button" class="secondary small" data-down aria-label="Mover etapa para baixo">↓</button></div>`}
 function bindOrder(){document.querySelectorAll('[data-up],[data-down]').forEach(el=>el.onclick=()=>{const row=el.parentElement;if(el.hasAttribute('data-up')&&row.previousElementSibling)row.parentElement.insertBefore(row,row.previousElementSibling);if(el.hasAttribute('data-down')&&row.nextElementSibling)row.parentElement.insertBefore(row.nextElementSibling,row)})}
 async function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Não foi possível ler a imagem.'));r.readAsDataURL(file)})}
 function accountDialog(account){const a=account||{},d=ctx.modal(a.id?'Configurar conta':'Adicionar conta',`<form><div class="grid2">${ctx.field('Nome da conta / caixa','name','text',a.name||'','required maxlength="150"')}${ctx.field('Saldo inicial (R$)','opening_balance','number',a.opening_balance??0,'required step="0.01"')}${ctx.field('Data do saldo inicial','opening_date','date',a.opening_date||today(),'required')}${check('Conta ativa para novos lançamentos','active',a.active??true)}</div><p class="note">O saldo inicial é o valor antes dos movimentos da data indicada. Movimentos anteriores continuam no histórico e não compõem este saldo. Alterações afetam a posição exibida da conta.</p><p class="error" role="alert"></p><div class="form-actions"><button type="button" class="secondary" data-close>Cancelar</button><button class="primary">Salvar conta</button></div></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;const fd=new FormData(e.target);try{await ctx.rpc('save_account',{p_id:a.id||null,p_name:fd.get('name'),p_opening:Number(fd.get('opening_balance')),p_date:fd.get('opening_date'),p_active:fd.has('active')});await ctx.load();d.close();settingsPage();ctx.toast('Conta salva.')}catch(err){d.querySelector('.error').textContent=err.message;e.submitter.disabled=false}}}
 Object.assign(ctx,{settingsPage,accountDialog});
}
